// DADOS 

var lat = latitude.value;
var lon = longitude.value;
var capacity = (KWp.value / 1000000); // GWp
var energia = energy.value; // GWh ano acumulado

// VALIDAÇÕES INICIAIS

if (!capacity || capacity <= 0) return 0;
if (!energia || energia < 0) energia = 0;

// DATA

var agora = new Date();
var ano = agora.getFullYear();
var mesAtual = agora.getMonth();
var diaAtual = agora.getDate();


// FUNÇÕES 

function rad(g) { return g * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }

function diaDoAno(data) {
    var inicio = new Date(data.getFullYear(), 0, 0);
    var diff = data - inicio;
    return Math.floor(diff / (1000 * 60 * 60 * 24));
}

function duracaoSolarDia(data) {
    var N = diaDoAno(data);
    var decl = 23.45 * Math.sin(rad((360/365) * (284 + N)));
    var cosW = -Math.tan(rad(lat)) * Math.tan(rad(decl));

    if (cosW > 1) cosW = 1;
    if (cosW < -1) cosW = -1;

    var W = deg(Math.acos(cosW));
    return (2 * W) / 15;
}

//  SOMA DAS HORAS SOLARES DESDE JANEIRO 

var horasTotal = 0;

// Meses completos
for (var m = 0; m < mesAtual; m++) {
    var diasNoMes = new Date(ano, m + 1, 0).getDate();
    for (var d = 1; d <= diasNoMes; d++) {
        horasTotal += duracaoSolarDia(new Date(ano, m, d));
    }
}

// Dias completos do mês atual
for (var d = 1; d < diaAtual; d++) {
    horasTotal += duracaoSolarDia(new Date(ano, mesAtual, d));
}


// HORAS DO DIA ATUAL 

var duracaoHoje = duracaoSolarDia(agora);

var fuso = -3;
var meridianoCentral = fuso * 15;
var correcaoLongitude = (lon - meridianoCentral) / 15;
var meioDiaSolar = 12 - correcaoLongitude;

var nascerSol = meioDiaSolar - duracaoHoje / 2;
var porSol = meioDiaSolar + duracaoHoje / 2;

var horaAtual = agora.getHours() + 
                agora.getMinutes()/60 + 
                agora.getSeconds()/3600;

var horasHoje;

if (horaAtual <= nascerSol) {
    horasHoje = 0;
} 
else if (horaAtual >= porSol) {
    horasHoje = duracaoHoje;
} 
else {
    horasHoje = horaAtual - nascerSol;
}

horasTotal += horasHoje;


// PROTEÇÃO FINAL 

if (horasTotal <= 0) return 0;


// FC ANUAL

var FC = (energia / (capacity * horasTotal)) * 100;


// CLAMP 0–100% 

if (isNaN(FC) || !isFinite(FC)) {
    return 0;
}

if (FC > 100) FC = 100;
if (FC < 0) FC = 0;

return FC;

